CREATE TABLE IF NOT EXISTS admins(id serial PRIMARY KEY,username text UNIQUE NOT NULL,password text NOT NULL);
CREATE TABLE IF NOT EXISTS web_sessions(token text PRIMARY KEY,admin_id int REFERENCES admins(id),expires timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY,value text NOT NULL);
CREATE TABLE IF NOT EXISTS groups(id serial PRIMARY KEY,name text UNIQUE NOT NULL CHECK(length(name) BETWEEN 1 AND 80));
CREATE TABLE IF NOT EXISTS proxies(id serial PRIMARY KEY,name text NOT NULL,host text NOT NULL,port int NOT NULL CHECK(port BETWEEN 1 AND 65535),username text NOT NULL DEFAULT '',password text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'unverified',detail text NOT NULL DEFAULT '',checked_at timestamptz);
CREATE TABLE IF NOT EXISTS accounts(id serial PRIMARY KEY,name text NOT NULL,phone text NOT NULL DEFAULT '',tg_user_id bigint UNIQUE,session text NOT NULL,fingerprint text UNIQUE NOT NULL,proxy_id int REFERENCES proxies(id),enabled boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'imported',detail text NOT NULL DEFAULT '',checked_at timestamptz,cooldown_until timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts(id serial PRIMARY KEY,name text NOT NULL DEFAULT '',phone text UNIQUE NOT NULL,company text NOT NULL DEFAULT '',country text NOT NULL DEFAULT '',username text NOT NULL DEFAULT '',group_id int REFERENCES groups(id),account_id int REFERENCES accounts(id),consent boolean NOT NULL DEFAULT false,optout boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS imports(id text PRIMARY KEY,rows jsonb NOT NULL,group_id int REFERENCES groups(id),confirmed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations(id serial PRIMARY KEY,account_id int NOT NULL REFERENCES accounts(id),peer_id bigint NOT NULL,name text NOT NULL,username text NOT NULL DEFAULT '',mode text NOT NULL DEFAULT 'human',ai_allowed boolean NOT NULL DEFAULT false,version int NOT NULL DEFAULT 0,stage text NOT NULL DEFAULT 'new',last_text text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,peer_id));
CREATE TABLE IF NOT EXISTS messages(id bigserial PRIMARY KEY,conversation_id int NOT NULL REFERENCES conversations(id),tg_id bigint NOT NULL,outgoing boolean NOT NULL,text text NOT NULL,sent_at timestamptz NOT NULL DEFAULT now(),UNIQUE(conversation_id,tg_id));
CREATE TABLE IF NOT EXISTS campaigns(id serial PRIMARY KEY,name text NOT NULL,group_id int NOT NULL REFERENCES groups(id),account_id int NOT NULL REFERENCES accounts(id),body text NOT NULL,state text NOT NULL DEFAULT 'paused',interval_seconds int NOT NULL CHECK(interval_seconds>=60),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox(id text PRIMARY KEY,account_id int NOT NULL REFERENCES accounts(id),conversation_id int REFERENCES conversations(id),contact_id int REFERENCES contacts(id),campaign_id int REFERENCES campaigns(id),peer text NOT NULL,body text NOT NULL,source text NOT NULL DEFAULT 'human',version int,random_id bigint UNIQUE NOT NULL,status text NOT NULL DEFAULT 'queued',detail text NOT NULL DEFAULT '',tg_id bigint,not_before timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(campaign_id,contact_id));
CREATE TABLE IF NOT EXISTS ai_runs(id bigserial PRIMARY KEY,conversation_id int REFERENCES conversations(id),version int,status text NOT NULL DEFAULT 'running',input_tokens int DEFAULT 0,output_tokens int DEFAULT 0,detail text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(conversation_id,version));
CREATE TABLE IF NOT EXISTS audit(id bigserial PRIMARY KEY,action text NOT NULL,detail text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(status,not_before);
CREATE INDEX IF NOT EXISTS messages_conversation ON messages(conversation_id,id);
INSERT INTO groups(name) VALUES ('默认分组') ON CONFLICT DO NOTHING;

ALTER TABLE contacts ADD COLUMN IF NOT EXISTS ai_consent boolean NOT NULL DEFAULT false;
